// 選択肢ヘルパー（このファイル内専用。_shared の mcq と同等）
function mcq2(question, choices, answerNum, explain) {
  return {
    q: `${question}\n${choices.map((c, i) => `${i + 1}) ${c}`).join('  ')}`,
    check: { type: 'answer', any: [String(answerNum)] },
    answerHint: '番号で回答',
    hints: ['各選択肢を吟味する', '消去法で絞る', `正解は ${answerNum} 番`],
    explain,
  };
}

